// One class, three audiences: finance, auditors, the database team
public sealed class Employee(TimeCard card, decimal rate)
{
    // Finance changed this to "overtime after 40 hours a week"
    private decimal RegularHours() => Math.Min(card.WeeklyHours, 40m);

    public decimal CalculatePay() =>
        RegularHours() * rate
        + (card.WeeklyHours - RegularHours()) * rate * 1.5m;

    // The auditors' report reuses finance's helper,
    // so finance's change moved the auditors' numbers too
    public string ReportHours() =>
        $"{card.EmployeeId}: {RegularHours()} regular hours";

    public void Save(IEmployeeStore store) => store.Save(card);
}

// Finance's rules: only payroll asks for changes here
public sealed class PayCalculator
{
    public decimal Calculate(TimeCard card, decimal rate)
    {
        var regular = Math.Min(card.WeeklyHours, 40m);
        var overtime = card.WeeklyHours - regular;
        return regular * rate + overtime * rate * 1.5m;
    }
}

// Operations' rules: only the auditors ask for changes here
public sealed class HoursReport
{
    public string Line(TimeCard card)
    {
        var regular = Math.Min(card.WeeklyHours, card.ContractHours);
        return $"{card.EmployeeId}: {regular} regular hours";
    }
}
